from usg.dsl import *

# Signalised crossing: crossing_9 with signal_3
cid, signal_id = "crossing_9", "signal_3"

SPEC = {
    "tasks": [
        {
            "name": "cross_with_traffic",
            "instruction": "Wait for green, then cross while avoiding the car.",
            "goal": {
                "op": "call",
                "name": "wait_for_green",
                "args": {
                    "zone": {
                        "kind": "crossing",
                        "id": "crossing_9"
                    },
                    "signal": "signal_3"
                }
            },
            "safety": [
                {
                    "op": "call",
                    "name": "collision_free",
                    "args": {
                        "entity": "Car1",
                        "r": 0.3
                    }
                }
            ],
            "timeout": {
                "initial": 60,
                "baseline": 90
            }
        }
    ]
}

scenario = ScenarioBuilder("cross_green_with_car", MAP, scenario_type="custom",
                           description="Wait for green at a signalised crossing while a car approaches.")
scenario.user(MAP.crossing_side(cid, "start", inset=2.0))

# Create the signal cycle for signal_3
signal_name = scenario.signal_cycle(cid, green=15, red=20, initial="red")

# Get the road ID and start position from the crossing object
crossings = MAP.crossings()
cr = next((c for c in crossings if c["id"] == cid), None)
if cr is None:
    raise ValueError(f"Crossing {cid} not found")

road_id = cr["road"]
s = cr["road_s"]
length = MAP.road(road_id)["length"]
route = MAP.drive_route(road_id, max(0.0, s - 30.0), min(length, s + 30.0), "forward")
scenario.vehicle("Car1", route[0], route[1:], speed=8.0, model="car_white", start_when=when_task_starts(None))

handles = scenario.apply_spec(SPEC)

